import styles from "./templates.module.css";

export function HighlightedText({ text }: { text: string }) {
  return text.split(/(\{\{\w+\}\})/g).map((part, index) =>
    /^\{\{\w+\}\}$/.test(part) ? (
      <span
        className={`${styles.token} py-[1px] px-2 rounded-[7px] [background:color-mix(in_srgb,_var(--accent)_22%,_transparent)] text-[var(--tpl-token)] [font:500_12.5px_var(--font-jetbrains),_monospace] [box-decoration-break:clone]`}
        key={index}
      >
        {part}
      </span>
    ) : (
      part
    ),
  );
}
